sksl:
uniform shader image;
uniform shader bright;
uniform float2 size;
uniform float time;
uniform float threshold;
uniform float blur;
uniform float intensity;
uniform float haloRadius;
uniform float haloAmount;
uniform float colors;
layout(color) uniform half4 colorA;
layout(color) uniform half4 colorB;
uniform float colorRange;
uniform float glowSat;
uniform float blend;
uniform float comp;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float3 sat3(float3 c, float s) {
    return mix(float3(dot(c, float3(0.2126, 0.7152, 0.0722))), c, s);
}
float3 blendm(float3 b, float3 s, float m) {
    if (m < 0.5) return s;
    if (m < 1.5) return b + s;
    if (m < 2.5) return 1.0 - (1.0 - b) * (1.0 - s);
    if (m < 3.5) return b * s;
    if (m < 4.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(float3(0.5), b));
    if (m < 5.5) return (1.0 - 2.0 * s) * b * b + 2.0 * s * b;
    if (m < 6.5) return max(b, s);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return abs(b - s);
    return b / max(1.0 - s, 0.001);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float4 g = float4(bright.eval(coord));
    float4 halo = float4(0.0);
    for (int i = 0; i < 8; i++) {
        float a = float(i) * 0.7853982;
        halo += float4(bright.eval(clamp(coord + float2(cos(a), sin(a)) * haloRadius, float2(0.0), size)));
    }
    g = g + halo * 0.125 * haloAmount;
    float gl = luma(g.rgb);
    float3 gc = colors < 0.5 ? g.rgb : mix(float3(colorA.rgb), float3(colorB.rgb), saturate(gl * colorRange)) * gl;
    gc = sat3(gc, glowSat) * intensity;
    float ga = g.a * intensity;
    float4 G = float4(gc, saturate(ga));
    float4 r = G;
    if (comp < 0.5) {
        float3 base = unp(c);
        float3 gS = gc / max(ga, 0.0001);
        float3 o = mix(base, blendm(base, gS, blend), ga);
        float a = max(c.a, saturate(ga));
        r = float4(max(o, float3(0.0)) * a, a);
    } else if (comp < 1.5) {
        r = G + c * (1.0 - G.a);
    }
    return fin(c, r, opacity);
}
